if(EditorApplication.isPlaying)throw new System.Exception("Edit required");var room=GameObject.Find("22 ShopWorkflow10 - isolated artistic reconstruction");var skins=room.GetComponentsInChildren<MeshFilter>().Where(m=>m.name.StartsWith("CM_SW10_Inside")).ToArray();if(room.transform.Find("CM_SW10_InteriorPlasterBatch")!=null)throw new System.Exception("Already batched");var combines=skins.Select(m=>new CombineInstance{mesh=m.sharedMesh,transform=m.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{name="CM_SW10_InteriorPlasterBatch"};mesh.CombineMeshes(combines,true,true);AssetDatabase.CreateAsset(mesh,"Assets/BlightBloom/Art/Interiors/CrookedMortar/ShopWorkflow10/FittedMeshes/CM_SW10_InteriorPlasterBatch.asset");var g=new GameObject(mesh.name);g.transform.SetParent(room.transform,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=skins[0].GetComponent<Renderer>().sharedMaterial;g.layer=2;foreach(var skin in skins)skin.GetComponent<Renderer>().enabled=false;AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());return new{sourceFaces=skins.Length,batchTriangles=mesh.triangles.Length/3,renderersSaved=skins.Length-1};
